import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1793739519000}'),s={name:"changelog.md"};function i(d,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Each entry says what ships, per package and app. <a href="./alpha-status">Alpha status</a> is the current picture; this page is the history. Versions follow semver on 0.x: a breaking change is a minor bump.</p><h2 id="_0-1-0-—-first-draft-2026-11-03" tabindex="-1">0.1.0 — first draft, 2026-11-03 <a class="header-anchor" href="#_0-1-0-—-first-draft-2026-11-03" aria-label="Permalink to &quot;0.1.0 — first draft, 2026-11-03&quot;">​</a></h2><p>The first version of every package and of the shell. Nothing is published to npm yet; the packages are used from the source repository, which is private during the alpha (<a href="./packages/#install">Packages</a>).</p><h3 id="kernl-guard-0-1-0" tabindex="-1"><code>@kernl/guard</code> 0.1.0 <a class="header-anchor" href="#kernl-guard-0-1-0" aria-label="Permalink to &quot;`@kernl/guard` 0.1.0&quot;">​</a></h3><ul><li>Three profiles, <code>strict</code>, <code>balanced</code> and <code>relaxed</code>, from <code>createGuardConfig</code>, and <code>applyNappletRules</code> for kehto&#39;s runtime firewall.</li><li>Envelope classification, ingress flood control with quarantine, the visibility gate, and the focus-aware firewall over <code>@kehto/firewall</code>&#39;s <code>evaluate()</code>.</li><li>The fixed zero-network CSP from <code>createAppletCsp</code>, with the Trusted Types directives the frame lock needs.</li><li>The nested-frame lock: a port of kehto&#39;s unreleased <code>experimental.nestedContextLock</code> (<a href="./decisions#d-014">D-014</a>), described under Security below.</li><li>Eleven mitigation descriptions for the guard panel. Pure; its one dependency is <code>@kehto/firewall</code>. See <a href="./packages/guard"><code>@kernl/guard</code></a>.</li></ul><h3 id="kernl-messaging-0-1-0" tabindex="-1"><code>@kernl/messaging</code> 0.1.0 <a class="header-anchor" href="#kernl-messaging-0-1-0" aria-label="Permalink to &quot;`@kernl/messaging` 0.1.0&quot;">​</a></h3><ul><li>The <code>MessagingProvider</code>, <code>MessagingBackend</code> and <code>MessagingRegistry</code> contracts, with saved-preference restore.</li><li>The composite backend with <code>provider:innerId</code> namespacing, and <code>describeProvider</code> rows.</li><li>A complete in-memory backend, <code>createMemoryBackend</code>, used by the preview and the tests.</li><li>Three providers, <code>private</code>, <code>legacy</code> and <code>ratchet</code>, built with <code>defineProvider</code> from backends the host injects. No real backend ships, so all three are unavailable in the live shell. See <a href="./packages/messaging"><code>@kernl/messaging</code></a>.</li></ul><h3 id="kernl-bridges-0-1-0" tabindex="-1"><code>@kernl/bridges</code> 0.1.0 <a class="header-anchor" href="#kernl-bridges-0-1-0" aria-label="Permalink to &quot;`@kernl/bridges` 0.1.0&quot;">​</a></h3><ul><li><code>parseLocator</code> for the web schemes, <code>magnet:</code>, <code>nzb:</code>, <code>slsk:</code> and <code>mailto:</code>, with <code>formatLocator</code> and <code>isNzbUrl</code>.</li><li>The <code>Bridge</code> contract, the registry with its <code>authorize</code> hook and outcome events, and <code>describeBridge</code> rows.</li><li>A complete HTTP bridge with an SSRF policy: <code>https</code> only, private and local destinations blocked, a byte limit on the streamed body, and opaque redirects refused in the browser.</li><li>The torrent, NZB, Soulseek and mail bridges, and <code>createHandoffBackends</code>, which serves all four by opening the locator&#39;s canonical address in an app on the user&#39;s device (<a href="./concepts/bridges#hand-off-backends">Bridges</a>).</li><li><code>createBridgeResourceResolver</code> for kehto&#39;s resource service. See <a href="./packages/bridges"><code>@kernl/bridges</code></a>.</li></ul><h3 id="kernl-core-0-1-0" tabindex="-1"><code>@kernl/core</code> 0.1.0 <a class="header-anchor" href="#kernl-core-0-1-0" aria-label="Permalink to &quot;`@kernl/core` 0.1.0&quot;">​</a></h3><ul><li><code>createKernl</code>, the composition root: one applesauce <code>EventStore</code>, <code>RelayPool</code> and <code>AccountManager</code> over kehto&#39;s <code>createShellBridge</code>, exercised end to end in <code>kernl.feature</code>.</li><li>Applet pointer decoding, manifest resolution, the mount plan and mounting.</li><li>Grants over <code>bridge.runtime.aclState</code>, the restrictive environment resolver, and consent summaries for destructive writes.</li><li><a href="./concepts/relay-tiers">Relay tiers</a>, <a href="./concepts/persistence">persistence</a> under the <code>kernl:</code> prefix with plaintext keys refused, the guard pipeline and runtime firewall rules, the default messaging and bridge registries, and four <a href="./concepts/layouts">layouts</a>. See <a href="./packages/core"><code>@kernl/core</code></a>.</li></ul><h3 id="shell-and-site-apps-web" tabindex="-1">Shell and site (<code>apps/web</code>) <a class="header-anchor" href="#shell-and-site-apps-web" aria-label="Permalink to &quot;Shell and site (`apps/web`)&quot;">​</a></h3><ul><li>The landing site at <code>/</code> and the shell at <code>/app/</code>.</li><li>Sign-in with a browser extension, a remote signer, a read-only address or a password-protected local account.</li><li>Open an applet by address, with its required and optional domains as choices.</li><li>Floating and tiled windows, with a compact layout at 720 px and below.</li><li>A grants panel per window, the shell-wide guard panel with its event log, the provider picker, and Settings for relay tiers.</li><li>The offline preview behind <code>?preview=1</code> (<a href="./decisions#d-011">D-011</a>), hosted at <a href="https://kernlize.github.io/app/?preview=1" target="_blank" rel="noreferrer">kernlize.github.io/app/?preview=1</a>.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><p>These pages, the TypeDoc API reference, <code>llms.txt</code> and a Markdown twin of every page, checked by <code>pnpm docs:check</code>: TypeDoc in strict mode, the docs audit, and every TypeScript sample compiled against the package sources.</p><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><p>The nested-frame lock (<a href="./decisions#d-014">D-014</a>) closes a path an independent review found: applet code could create a child frame whose fresh realm still had a working <code>RTCPeerConnection</code>, which reached a public STUN server. <code>@kehto/shell</code> 0.29.0 removes the peer-connection globals from the applet&#39;s own realm only, and CSP does not govern WebRTC. The lock has three parts:</p><ul><li><strong>Static markup.</strong> <code>assertAppletHasNoFrame</code> refuses frame, object and embed markup in the verified bytes with <code>denied:nested-frame</code> before they become a srcdoc.</li><li><strong>Creation.</strong> <code>renderFrameLockScript</code> installs a Trusted Types <code>default</code> policy that refuses frame markup at every HTML string sink, and pins the element factories so they refuse frame tag names. It runs before any applet script.</li><li><strong>Insertion.</strong> A second review found four creation routes past the factory pins. Because a frame only gets a realm once it is connected to the document, <code>appletInsertionLock</code> pins every DOM insertion method, including <code>Range.insertNode</code> and <code>Range.surroundContents</code>. It refuses any node that is, or contains, an HTML-namespace frame element. It reads node identity through native getters captured before applet code runs, refuses custom elements that extend frame elements, and removes <code>XSLTProcessor</code>.</li></ul><p><code>tests/e2e/applet-network-sealed.spec.ts</code> probes every route the reviews found, and thirteen insertion routes, and sees no child realm and no candidate. The cost: every DOM insertion in an applet walks the inserted subtree once.</p><h3 id="corrections" tabindex="-1">Corrections <a class="header-anchor" href="#corrections" aria-label="Permalink to &quot;Corrections&quot;">​</a></h3><p>Recorded in <a href="./alpha-status#corrections">Alpha status</a>, both on 2026-11-03:</p><ul><li><strong>Rate enforcement.</strong> Earlier drafts said kehto&#39;s runtime firewall refused envelopes over the profile&#39;s rates. It did not, because <code>applyRuntimeFirewallRules</code> also set each applet&#39;s runtime policy to <code>allow</code>, which passes before any rate is checked. The policy call is removed, the rates and kehto&#39;s startup burst guard now refuse before dispatch, and <a href="./decisions#d-012">D-012</a> is rewritten.</li><li><strong>Size caps.</strong> The guard&#39;s size matchers were described as able to fire in the shell. The ingress guard rejects the same envelopes first, so they could not. Oversized downloads and queries were reported but still handled; they are now refused before dispatch.</li></ul>',23)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
